import { IonButton, IonContent, IonItem, IonList, IonNote, IonTextarea, IonToggle } from '@ionic/react';
export default function MissionScreen({ mission, setMission, action, setAction, speech, setSpeech, haptics, setHaptics, onNavigateMonitor, onNavigateOptimize }) { return <IonContent className="aura-page"><h1 className="page-heading">Set your mission</h1><p className="page-subtitle">Describe what Aura should notice and how it should respond.</p><IonList inset><IonItem><IonTextarea label="Watch for" labelPlacement="stacked" value={mission} onIonInput={e => setMission(e.detail.value || '')} placeholder="Alert if someone is loitering near the front door." autoGrow /></IonItem><IonItem><IonTextarea label="On alert, announce" labelPlacement="stacked" value={action} onIonInput={e => setAction(e.detail.value || '')} placeholder="Tell the person they are being recorded and to leave." autoGrow /></IonItem><IonItem><IonToggle checked={speech} onIonChange={e => setSpeech(e.detail.checked)}>Speak alerts</IonToggle></IonItem><IonItem><IonToggle checked={haptics} onIonChange={e => setHaptics(e.detail.checked)}>Vibrate</IonToggle></IonItem></IonList><IonNote className="ion-padding">Improve detection with examples in <IonButton fill="clear" size="small" onClick={onNavigateOptimize}>Optimize</IonButton>.</IonNote><div className="wide-action"><IonButton expand="block" size="large" onClick={onNavigateMonitor}>Deploy &amp; arm</IonButton></div></IonContent>; }
